val writerThread = HandlerThread("file-writer").apply { start() }
val writerHandler = Handler(writerThread.looper)

fun writeLog(text: String) {
    writerHandler.post {
        // serialized: runs one at a time on the same thread
        logFile.appendText(text + "\n")
    }
}

