class ItemProvider : ContentProvider() {
    private val uriMatcher = UriMatcher(UriMatcher.NO_MATCH).apply {
        addURI(AUTHORITY, "items", ITEMS)
        addURI(AUTHORITY, "items/#", ITEM_ID)
    }

    override fun onCreate(): Boolean = true

    override fun query(
        uri: Uri, projection: Array<out String>?, selection: String?,
        selectionArgs: Array<out String>?, sortOrder: String?
    ): Cursor? {
        val match = uriMatcher.match(uri)
        val selectionToUse = if (match == ITEM_ID)
            "_id=" + uri.lastPathSegment else selection
        return db.query("items", projection, selectionToUse, selectionArgs, null, null, sortOrder)
    }

    override fun insert(uri: Uri, values: ContentValues?): Uri? {
        val id = db.insert("items", null, values)
        context?.contentResolver?.notifyChange(uri, null)   // observers react
        return ContentUris.withAppendedId(uri, id)
    }
}

private val takePicture = registerForActivityResult(
    ActivityResultContracts.TakePicture()
) { success ->
    if (success) showImage(photoUri) else toast("Capture cancelled")
}

fun capture() {
    photoUri = createImageUri()      // MediaStore insert: owns the capture
    takePicture.launch(photoUri)
}

private fun createImageUri(): Uri {
    val values = ContentValues().apply {
        put(MediaStore.Images.Media.DISPLAY_NAME, "capture_${System.currentTimeMillis()}.jpg")
        put(MediaStore.Images.Media.MIME_TYPE, "image/jpeg")
    }
    return contentResolver.insert(
        MediaStore.Images.Media.EXTERNAL_CONTENT_URI, values
    )!!
}

class SwipeView @JvmOverloads constructor(
    context: Context, attrs: AttributeSet? = null
) : View(context, attrs) {

    override fun onTouchEvent(event: MotionEvent): Boolean {
        when (event.actionMasked) {
            MotionEvent.ACTION_DOWN -> {
                parent?.requestDisallowInterceptTouchEvent(true)
                return true      // we own this gesture from DOWN
            }
            MotionEvent.ACTION_UP, MotionEvent.ACTION_CANCEL -> {
                parent?.requestDisallowInterceptTouchEvent(false)
                return true
            }
        }
        return true
    }
}

class ConfirmDialog : DialogFragment() {
    override fun onStart() {
        super.onStart()
        // DialogFragment provides the themed activity context automatically
        dialog?.setTitle("Confirm")
        dialog?.findViewById<Button>(R.id.ok)?.setOnClickListener {
            dismiss()
        }
    }
}

fun showFromRepo(appContext: Context) {
    // Wrong: application context has no window token -> BadTokenException
    // AlertDialog.Builder(appContext).show()

    // Right: the dialog belongs to a window-token owner
    supportFragmentManager.beginTransaction()
        .add(ConfirmDialog(), "confirm")
        .commitNow()
}

fun ensureBatteryExemption(context: Context) {
    val pm = context.getSystemService(PowerManager::class.java)
    if (pm.isIgnoringBatteryOptimizations(context.packageName)) return

    if (pm.isPowerSaveMode) return       // user asked for aggressive saving

    val intent = Intent(
        Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS,
        Uri.parse("package:${context.packageName}")
    )
    context.startActivity(intent)        // special access screen, user decides
}
